const h=()=>{const c=(e,t=90)=>e?e.length<=t?e:`${e.slice(0,t)}…`:"",u=(e,t="YYYY-MM-DD HH:mm")=>{if(!e)return"";const n=new Date(e);if(isNaN(n.getTime()))return"";const r=a=>a.toString().padStart(2,"0"),o={YYYY:n.getFullYear(),MM:r(n.getMonth()+1),DD:r(n.getDate()),HH:r(n.getHours()),mm:r(n.getMinutes()),ss:r(n.getSeconds())};let s=t;return Object.keys(o).forEach(a=>{s=s.replace(a,o[a])}),s};function g(e){const t=new Date(e),r=["Chủ Nhật","Thứ Hai","Thứ Ba","Thứ Tư","Thứ Năm","Thứ Sáu","Thứ Bảy"][t.getDay()],o=String(t.getDate()).padStart(2,"0"),s=String(t.getMonth()+1).padStart(2,"0"),a=t.getFullYear(),i=String(t.getHours()).padStart(2,"0"),d=String(t.getMinutes()).padStart(2,"0");return`${r}, ${o}/${s}/${a} - ${i}:${d}`}return{truncateText:c,date:u,formatVNTime:g}};export{h as _};
